package br.com.bancohorizonte.service; import br.com.bancohorizonte.dto.*; import br.com.bancohorizonte.entity.Pessoa; import br.com.bancohorizonte.exception.*; import br.com.bancohorizonte.repository.PessoaRepository; import jakarta.persistence.*;
public class PessoaService { private final EntityManager em; private final PessoaRepository repo; public PessoaService(EntityManager em){this.em=em;repo=new PessoaRepository(em);} public PessoaResponse criar(PessoaRequest r){validar(r);EntityTransaction tx=em.getTransaction();try{tx.begin();if(repo.existeCpf(r.cpf()))throw new CpfJaCadastradoException(r.cpf());Pessoa p=new Pessoa(r.nome().trim(),r.cpf(),r.email().trim());repo.salvar(p);tx.commit();return map(p);}catch(RuntimeException e){if(tx.isActive())tx.rollback();throw e;}} private void validar(PessoaRequest r){if(r==null||vazia(r.nome())||r.cpf()==null||!r.cpf().matches("\\d{11}")||r.email()==null||!r.email().matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new BusinessException("Dados de pessoa inválidos.");} private boolean vazia(String s){return s==null||s.isBlank();} private PessoaResponse map(Pessoa p){return new PessoaResponse(p.getId(),p.getNome(),p.getCpf(),p.getEmail());} }
